import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        String[] words = new String[(int) n];
        for (int i = 0; i < words.length; i++) words[i] = next();

        int count = (int) n;
        int[] masks = new int[count];
        int[] lens = new int[count];
        for (int i = 0; i < count; i++) {
            for (int k = 0; k < words[i].length(); k++) masks[i] |= 1 << (words[i].charAt(k) - 'a');
            lens[i] = words[i].length();
        }
        long best = 0;
        for (int i = 0; i < count; i++) {
            for (int j = i + 1; j < count; j++) {
                if ((masks[i] & masks[j]) == 0) best = Math.max(best, (long) lens[i] * lens[j]);
            }
        }
        System.out.println(best);
    }
}
